  Definition cR_pre (rg : bvmap 5 word) : Prop :=
    getr rg 10 = Z_to_bv 64 pd /\ getr rg 11 = Z_to_bv 64 ps /\ getr rg 12 = Z_to_bv 64 n /\ getr rg 8 = Z_to_bv 64 s
    /\ getr rg 2 = Z_to_bv 64 (s - 2144).
  Definition cR_post (rg : bvmap 5 word) : Prop := ltac2:(Rpl.RP.run_i (rplG ()) 1 "S=0|21;!1,20!1,2|600;!1+12|32;!1,44!1,4|33;!1,4|34;|30;!1,48!1,4|44;|10;!1,4;$rg;R!2'_Q13!2+A!3+<3!2'_S#1!3,315vv,6!2'715!2'=2/pd;!2+A!3+<3!2'_S#1!3,316vv,6!2'716!2'=2/ps;!2+A!3+<3!2'_S#1!3,317vv,6!2'717!2'=2/n;!2+A!3+<3!2'_S#1!3,319vv,6!2'719!2'=2/s;!2+A!3+<3!2'_S#1!3,31:vv,6!2'71:!2'=2!2'H/n;!1,4|601;!3+<3!2'_S#1!3,31<vv,6!2'71<!2'=2!2'H/s;!1,4|;060;").

