  (* [comment removed for export] *)
  Corollary wrap_memmove_run : forall regs,
    getr regs 10 = Z_to_bv 64 pd -> getr regs 11 = Z_to_bv 64 ps -> getr regs 12 = Z_to_bv 64 n -> getr regs 2 = sp -> getr regs 1 = ra ->
    exists regs' Mj,
      msteps ASEGS (mkst regs (0x80238 : word) mem0 rom) (mkst regs' ra (mm_result Mj (Z_to_bv 64 pd) (Z_to_bv 64 ps) bs) rom)
